#!/usr/bin/env bash
#
# Bring a release branch up to date with <base-ref> and re-number its release:
#   1. merge <base-ref> (VERSION and CHANGELOG.md are taken from <base-ref>;
#      README.md conflicts are resolved only if they are version examples)
#   2. bump-release.sh again with the branch's own release notes and level
#      (3.0.8 -> 3.0.9 is a patch, 3.0.8 -> 3.1.0 a minor release, ...)
#
# Every merge to master is a release, so a PR prepared against an older
# master claims a VERSION that is taken by now. Renovate and the security
# scan rebuild their own PRs; refresh-release-prs.yml runs this for PRs
# labelled `auto-version`, and it works the same locally:
#   git fetch origin && .github/scripts/refresh-release-pr.sh origin/master
#
# Leaves a merge commit on success, does nothing if the branch is up to date
# or carries no release, and exits 1 (merge aborted) on conflicts that need a
# human.
#
# Usage: refresh-release-pr.sh <base-ref>

set -euo pipefail

if [ "$#" -ne 1 ]; then
    echo "Usage: $0 <base-ref>" >&2
    exit 2
fi
BASE_REF=$1
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)

if ! git diff --quiet || ! git diff --cached --quiet; then
    echo "::error::Uncommitted changes - commit or stash them first." >&2
    exit 1
fi

if git merge-base --is-ancestor "$BASE_REF" HEAD; then
    echo "Up to date with ${BASE_REF}."
    exit 0
fi

version_at() { git show "${1}:VERSION" | tr -d '[:space:]'; }

OLD_BASE=$(git merge-base HEAD "$BASE_REF")
OLD_VERSION=$(version_at "$OLD_BASE")
HEAD_VERSION=$(version_at HEAD)

if [ "$HEAD_VERSION" = "$OLD_VERSION" ]; then
    echo "No release on this branch (VERSION ${HEAD_VERSION} unchanged) - nothing to re-number."
    exit 0
fi

IFS=. read -r OLD_MAJOR OLD_MINOR _ <<<"$OLD_VERSION"
IFS=. read -r HEAD_MAJOR HEAD_MINOR _ <<<"$HEAD_VERSION"
if [ "$HEAD_MAJOR" != "$OLD_MAJOR" ]; then
    LEVEL="major"
elif [ "$HEAD_MINOR" != "$OLD_MINOR" ]; then
    LEVEL="minor"
else
    LEVEL="patch"
fi

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# The branch's release notes: the body of its newest CHANGELOG entry
# (including its '### Section' headings), without surrounding blank lines.
if ! git show HEAD:CHANGELOG.md | grep -m 1 '^## \[' | grep -qF "[${HEAD_VERSION}]"; then
    echo "::error::The newest CHANGELOG.md entry is not for VERSION ${HEAD_VERSION}." >&2
    exit 1
fi
git show HEAD:CHANGELOG.md | awk '
    /^## \[/ { if (n++) exit; next }
    n { lines[++c] = $0 }
    END {
        s = 1; while (s <= c && lines[s] ~ /^[[:space:]]*$/) s++
        e = c; while (e >= s && lines[e] ~ /^[[:space:]]*$/) e--
        for (i = s; i <= e; i++) print lines[i]
    }' > "$TMP/entries.md"

# A failed merge is fine if it stopped on conflicts (resolved below), not if
# it never started
if ! git merge --no-commit --no-ff "$BASE_REF" >/dev/null 2>&1 \
    && ! git rev-parse -q --verify MERGE_HEAD >/dev/null; then
    echo "::error::Merging ${BASE_REF} failed to start." >&2
    exit 1
fi

# Re-generated by bump-release.sh below
git checkout "$BASE_REF" -- VERSION CHANGELOG.md

# README.md conflicts are fine to resolve automatically if both sides only
# differ in image tag examples, which bump-release.sh rewrites anyway (same
# patterns). Any other difference - e.g. a dependency version - stays a
# conflict for a human.
if git diff --name-only --diff-filter=U | grep -qx README.md; then
    for stage in 1 2 3; do git show ":${stage}:README.md" > "$TMP/readme.${stage}"; done
    normalize() {
        perl -pe '
            s/(spatialite-base-image:)(alpine|ubuntu|alpine-dev|ubuntu-dev|dev)-\d+\.\d+\.\d+/${1}${2}-X.Y.Z/g;
            s/(spatialite-base-image:)\d+\.\d+\.\d+(?=[^.\d]|$)/${1}X.Y.Z/g;
        '
    }
    git merge-file -p --ours "$TMP/readme.2" "$TMP/readme.1" "$TMP/readme.3" | normalize > "$TMP/ours" || true
    git merge-file -p --theirs "$TMP/readme.2" "$TMP/readme.1" "$TMP/readme.3" | normalize > "$TMP/theirs" || true
    if cmp -s "$TMP/ours" "$TMP/theirs"; then
        git merge-file -p --theirs "$TMP/readme.2" "$TMP/readme.1" "$TMP/readme.3" > README.md || true
        git add README.md
    fi
fi

CONFLICTS=$(git diff --name-only --diff-filter=U | paste -sd " " -)
if [ -n "$CONFLICTS" ]; then
    git merge --abort
    echo "::error::Merging ${BASE_REF} conflicts in: ${CONFLICTS}" >&2
    exit 1
fi

"${SCRIPT_DIR}/bump-release.sh" --level "$LEVEL" "$BASE_REF" - "$TMP/entries.md"
NEW_VERSION=$(cat VERSION)

git add VERSION CHANGELOG.md README.md
git commit --quiet --no-edit -m "Merge ${BASE_REF}, re-release ${HEAD_VERSION} as ${NEW_VERSION}"
echo "Re-released ${HEAD_VERSION} as ${NEW_VERSION} on top of ${BASE_REF} (${LEVEL})."
